PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE organizations(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE locations(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, zone TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','scheduler','provider','reception','customer')));
CREATE TABLE services(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, duration_min INTEGER NOT NULL CHECK(duration_min BETWEEN 5 AND 480), before_buffer_min INTEGER NOT NULL DEFAULT 0, after_buffer_min INTEGER NOT NULL DEFAULT 0, price_cents INTEGER NOT NULL CHECK(price_cents>=0));
CREATE TABLE staff(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), location_id TEXT NOT NULL REFERENCES locations(id), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE resources(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), location_id TEXT NOT NULL REFERENCES locations(id), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('room','equipment')), capacity INTEGER NOT NULL DEFAULT 1 CHECK(capacity>0), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE staff_services(staff_id TEXT NOT NULL REFERENCES staff(id), service_id TEXT NOT NULL REFERENCES services(id), PRIMARY KEY(staff_id,service_id));
CREATE TABLE availability_rules(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), staff_id TEXT NOT NULL REFERENCES staff(id), weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7), start_local TEXT NOT NULL, end_local TEXT NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT NOT NULL);
CREATE TABLE availability_exceptions(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), staff_id TEXT, location_id TEXT, start_utc TEXT NOT NULL, end_utc TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('closed','added')), reason TEXT NOT NULL);
CREATE TABLE holds(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), customer_id TEXT NOT NULL REFERENCES users(id), service_id TEXT NOT NULL REFERENCES services(id), location_id TEXT NOT NULL REFERENCES locations(id), staff_id TEXT NOT NULL REFERENCES staff(id), resource_id TEXT REFERENCES resources(id), start_utc TEXT NOT NULL, end_utc TEXT NOT NULL, allocation_start_utc TEXT NOT NULL, allocation_end_utc TEXT NOT NULL, display_zone TEXT NOT NULL, expires_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('active','confirmed','expired','cancelled')), idempotency_key TEXT NOT NULL, UNIQUE(organization_id,idempotency_key));
CREATE TABLE appointments(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), customer_id TEXT NOT NULL REFERENCES users(id), service_id TEXT NOT NULL REFERENCES services(id), location_id TEXT NOT NULL REFERENCES locations(id), staff_id TEXT NOT NULL REFERENCES staff(id), resource_id TEXT REFERENCES resources(id), start_utc TEXT NOT NULL, end_utc TEXT NOT NULL, allocation_start_utc TEXT NOT NULL, allocation_end_utc TEXT NOT NULL, display_zone TEXT NOT NULL, state TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, price_cents INTEGER NOT NULL, booking_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(organization_id,booking_key));
CREATE INDEX appointment_staff_interval ON appointments(staff_id,allocation_start_utc,allocation_end_utc) WHERE state!='cancelled';
CREATE TABLE appointment_history(id INTEGER PRIMARY KEY AUTOINCREMENT, appointment_id TEXT NOT NULL REFERENCES appointments(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, from_state TEXT, to_state TEXT, reason TEXT, at TEXT NOT NULL, snapshot TEXT NOT NULL);
CREATE TABLE waitlist(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, service_id TEXT NOT NULL, location_id TEXT NOT NULL, customer_id TEXT NOT NULL, earliest TEXT NOT NULL, latest TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('waiting','offered','booked','expired')), offer_expires_at TEXT);
CREATE TABLE reminders(id TEXT PRIMARY KEY, appointment_id TEXT NOT NULL REFERENCES appointments(id), scheduled_at TEXT NOT NULL, channel TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('pending','delivered','failed','dead')), attempts INTEGER NOT NULL DEFAULT 0, dedupe_key TEXT NOT NULL UNIQUE, last_error TEXT);
